import{_ as p,a0 as o,w as l,s as r,ao as d,I as i,x as a,a1 as n,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 Debian 10 中配置 Chroot 环境的 SFTP 服务 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Debian 10 中配置 Chroot 环境的 SFTP 服务 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Debian 10 中配置 Chroot 环境的 SFTP 服务 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Debian 10 中配置 Chroot 环境的 SFTP 服务 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20190915 How to Configure SFTP Server with Chroot in Debian 10","title":"如何在 Debian 10 中配置 Chroot 环境的 SFTP 服务","tag":"202005","desc":""},"relativePath":"202005/20190915 How to Configure SFTP Server with Chroot in Debian 10.md","filePath":"[post].md"}'),c={name:"202005/20190915 How to Configure SFTP Server with Chroot in Debian 10.md"};function h(g,s,u,f,b,k){const e=o("Link");return l(),r("div",null,[s[15]||(s[15]=d(`<h1 id="如何在-debian-10-中配置-chroot-环境的-sftp-服务" tabindex="-1">如何在 Debian 10 中配置 Chroot 环境的 SFTP 服务 <a class="header-anchor" href="#如何在-debian-10-中配置-chroot-环境的-sftp-服务" aria-label="Permalink to “如何在 Debian 10 中配置 Chroot 环境的 SFTP 服务”">​</a></h1><p>SFTP 意思是“<ruby>安全文件传输协议<rt>Secure File Transfer Protocol</rt></ruby>” 或 “<ruby>SSH 文件传输协议<rt>SSH File Transfer Protocol</rt></ruby>”，它是最常用的用于通过 <code>ssh</code> 将文件从本地系统安全地传输到远程服务器的方法，反之亦然。<code>sftp</code> 的主要优点是，除 <code>openssh-server</code> 之外，我们不需要安装任何额外的软件包，在大多数的 Linux 发行版中，<code>openssh-server</code> 软件包是默认安装的一部分。<code>sftp</code> 的另外一个好处是，我们可以允许用户使用 <code>sftp</code> ，而不允许使用 <code>ssh</code> 。</p><p><img src="https://img.linux.net.cn/data/attachment/album/202005/05/223518ip4mbdi4nggbdtgu.jpg" alt=""></p><p>当前发布的 Debian 10 代号为 ‘Buster’，在这篇文章中，我们将演示如何在 Debian 10 系统中在 “监狱式的” Chroot 环境中配置 <code>sftp</code>。在这里，Chroot 监狱式环境意味着，用户不能超出各自的家目录，或者用户不能从各自的家目录更改目录。下面实验的详细情况：</p><ul><li>OS = Debian 10</li><li>IP 地址 = 192.168.56.151</li></ul><p>让我们跳转到 SFTP 配置步骤，</p><h3 id="步骤-1、使用-groupadd-命令给-sftp-创建一个组" tabindex="-1">步骤 1、使用 groupadd 命令给 sftp 创建一个组 <a class="header-anchor" href="#步骤-1、使用-groupadd-命令给-sftp-创建一个组" aria-label="Permalink to “步骤 1、使用 groupadd 命令给 sftp 创建一个组”">​</a></h3><p>打开终端，使用下面的 <code>groupadd</code> 命令创建一个名为的 <code>sftp_users</code> 组：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# groupadd sftp_users</span></span></code></pre></div><h3 id="步骤-2、添加用户到组-sftp-users-并设置权限" tabindex="-1">步骤 2、添加用户到组 sftp_users 并设置权限 <a class="header-anchor" href="#步骤-2、添加用户到组-sftp-users-并设置权限" aria-label="Permalink to “步骤 2、添加用户到组 sftp_users 并设置权限”">​</a></h3><p>假设你想创建新的用户，并且想添加该用户到 <code>sftp_users</code> 组中，那么运行下面的命令，</p><p><strong>语法：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#  useradd -m -G sftp_users &lt;用户名&gt;</span></span></code></pre></div><p>让我们假设用户名是 <code>jonathan</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# useradd -m -G sftp_users jonathan</span></span></code></pre></div><p>使用下面的 <code>chpasswd</code> 命令设置密码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# echo &quot;jonathan:&lt;输入密码&gt;&quot; | chpasswd</span></span></code></pre></div><p>假设你想添加现有的用户到 <code>sftp_users</code> 组中，那么运行下面的 <code>usermod</code> 命令，让我们假设已经存在的用户名称是 <code>chris</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# usermod -G sftp_users chris</span></span></code></pre></div><p>现在设置用户所需的权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# chown root /home/jonathan /home/chris/</span></span></code></pre></div><p>在各用户的家目录中都创建一个上传目录，并设置正确地所有权：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# mkdir /home/jonathan/upload</span></span>
<span class="line"><span>root@linuxtechi:~# mkdir /home/chris/upload</span></span>
<span class="line"><span>root@linuxtechi:~# chown jonathan /home/jonathan/upload</span></span>
<span class="line"><span>root@linuxtechi:~# chown chris /home/chris/upload</span></span></code></pre></div><p><strong>注意:</strong> 像 Jonathan 和 Chris 之类的用户可以从他们的本地系统上传文件和目录。</p><h3 id="步骤-3、编辑-sftp-配置文件-etc-ssh-sshd-config" tabindex="-1">步骤 3、编辑 sftp 配置文件 /etc/ssh/sshd_config <a class="header-anchor" href="#步骤-3、编辑-sftp-配置文件-etc-ssh-sshd-config" aria-label="Permalink to “步骤 3、编辑 sftp 配置文件 /etc/ssh/sshd_config”">​</a></h3><p>正如我们已经陈述的，<code>sftp</code> 操作是通过 <code>ssh</code> 完成的，所以它的配置文件是 <code>/etc/ssh/sshd_config</code>，在做任何更改前，我建议首先备份文件，然后再编辑该文件，接下来添加下面的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# cp /etc/ssh/sshd_config /etc/ssh/sshd_config-org</span></span>
<span class="line"><span>root@linuxtechi:~# vim /etc/ssh/sshd_config</span></span>
<span class="line"><span>......</span></span>
<span class="line"><span>#Subsystem      sftp    /usr/lib/openssh/sftp-server</span></span>
<span class="line"><span>Subsystem       sftp    internal-sftp</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Match Group sftp_users</span></span>
<span class="line"><span>  X11Forwarding no</span></span>
<span class="line"><span>  AllowTcpForwarding no</span></span>
<span class="line"><span>  ChrootDirectory %h</span></span>
<span class="line"><span>  ForceCommand internal-sftp</span></span>
<span class="line"><span>......</span></span></code></pre></div><p>保存并退出文件。</p><p>为使上述更改生效，使用下面的 <code>systemctl</code> 命令来重新启动 <code>ssh</code> 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# systemctl restart sshd</span></span></code></pre></div><p>在上面的 <code>sshd_config</code> 文件中，我们已经注释掉了以 <code>Subsystem</code> 开头的行，并添加了新的条目 <code>Subsystem sftp internal-sftp</code> 和新的行。而</p><p><code>Match Group sftp_users</code> –&gt; 它意味着如果用户是 <code>sftp_users</code> 组中的一员，那么将应用下面提到的规则到这个条目。</p><p><code>ChrootDierctory %h</code> –&gt; 它意味着用户只能在他们自己各自的家目录中更改目录，而不能超出他们各自的家目录。或者换句话说，我们可以说用户是不允许更改目录的。他们将在他们的目录中获得监狱一样的环境，并且不能访问其他用户的目录和系统的目录。</p><p><code>ForceCommand internal-sftp</code> –&gt; 它意味着用户仅被限制到只能使用 <code>sftp</code> 命令。</p><h3 id="步骤-4、测试和验证-sftp" tabindex="-1">步骤 4、测试和验证 sftp <a class="header-anchor" href="#步骤-4、测试和验证-sftp" aria-label="Permalink to “步骤 4、测试和验证 sftp”">​</a></h3><p>登录到你的 <code>sftp</code> 服务器的同一个网络上的任何其它的 Linux 系统，然后通过我们放入 <code>sftp_users</code> 组中的用户来尝试 ssh 和 sftp 服务。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# ssh root@linuxtechi</span></span>
<span class="line"><span>root@linuxtechi&#39;s password:</span></span>
<span class="line"><span>Write failed: Broken pipe</span></span>
<span class="line"><span>[root@linuxtechi ~]# ssh root@linuxtechi</span></span>
<span class="line"><span>root@linuxtechi&#39;s password:</span></span>
<span class="line"><span>Write failed: Broken pipe</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>以上操作证实用户不允许 <code>ssh</code> ，现在使用下面的命令尝试 <code>sftp</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# sftp root@linuxtechi</span></span>
<span class="line"><span>root@linuxtechi&#39;s password:</span></span>
<span class="line"><span>Connected to 192.168.56.151.</span></span>
<span class="line"><span>sftp&gt; ls -l</span></span>
<span class="line"><span>drwxr-xr-x    2 root     1001         4096 Sep 14 07:52 debian10-pkgs</span></span>
<span class="line"><span>-rw-r--r--    1 root     1001          155 Sep 14 07:52 devops-actions.txt</span></span>
<span class="line"><span>drwxr-xr-x    2 1001     1002         4096 Sep 14 08:29 upload</span></span></code></pre></div><p>让我们使用 sftp 的 <code>get</code> 命令来尝试下载一个文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sftp&gt; get devops-actions.txt</span></span>
<span class="line"><span>Fetching /devops-actions.txt to devops-actions.txt</span></span>
<span class="line"><span>/devops-actions.txt                                                                               100%  155     0.2KB/s   00:00</span></span>
<span class="line"><span>sftp&gt;</span></span>
<span class="line"><span>sftp&gt; cd /etc</span></span>
<span class="line"><span>Couldn&#39;t stat remote file: No such file or directory</span></span>
<span class="line"><span>sftp&gt; cd /root</span></span>
<span class="line"><span>Couldn&#39;t stat remote file: No such file or directory</span></span>
<span class="line"><span>sftp&gt;</span></span></code></pre></div><p>上面的输出证实我们能从我们的 sftp 服务器下载文件到本地机器，除此之外，我们也必须测试用户不能更改目录。</p><p>让我们在 <code>upload</code> 目录下尝试上传一个文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sftp&gt; cd upload/</span></span>
<span class="line"><span>sftp&gt; put metricbeat-7.3.1-amd64.deb</span></span>
<span class="line"><span>Uploading metricbeat-7.3.1-amd64.deb to /upload/metricbeat-7.3.1-amd64.deb</span></span>
<span class="line"><span>metricbeat-7.3.1-amd64.deb                                                                        100%   38MB  38.4MB/s   00:01</span></span>
<span class="line"><span>sftp&gt; ls -l</span></span>
<span class="line"><span>-rw-r--r--    1 1001     1002     40275654 Sep 14 09:18 metricbeat-7.3.1-amd64.deb</span></span>
<span class="line"><span>sftp&gt;</span></span></code></pre></div><p>这证实我们已经成功地从我们的本地系统上传一个文件到 sftp 服务中。</p><p>现在使用 winscp 工具来测试 sftp 服务，输入 sftp 服务器 IP 地址和用户的凭证：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Winscp-sftp-debian10.jpg" alt=""></p><p>在 “Login” 上单击，然后尝试下载和上传文件：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Download-file-winscp-debian10-sftp.jpg" alt=""></p><p>现在，在 <code>upload</code> 文件夹中尝试上传文件：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Upload-File-using-winscp-Debian10-sftp.jpg" alt=""></p><p>上面的窗口证实上传是完好地工作的，这就是这篇文章的全部。如果这些步骤能帮助你在 Debian 10 中使用 chroot 环境配置 SFTP 服务器s，那么请分享你的反馈和评论。</p><hr>`,53)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"https://www.linuxtechi.com/configure-sftp-chroot-debian10/"},{default:t(()=>[...s[0]||(s[0]=[a("https://www.linuxtechi.com/configure-sftp-chroot-debian10/",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),n(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...s[2]||(s[2]=[a("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),n(e,{href:"https://github.com/robsean"},{default:t(()=>[...s[4]||(s[4]=[a("robsean",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const y=p(c,[["render",h]]);export{C as __pageData,y as default};
